"""Author original CodeClash problems. Executes only project-owned reference code."""
import json, random, re, itertools, math, bisect, heapq, collections
from pathlib import Path
rng=random.Random(314159)
bank=[]
preamble='import json, sys, math, bisect, heapq, itertools\nfrom collections import Counter, defaultdict, deque\n'
def add(title,topic,description,body,cases,difficulty='Easy',time='O(n)',space='O(n)'):
    ns={};exec(preamble+'def solve(data):\n'+''.join('    '+line+'\n' for line in body.splitlines()),ns)
    fixtures=[]
    for data in cases:
        result=ns['solve'](data)
        fixtures.append({'input':json.dumps(data,separators=(',',':'))+'\n','output':json.dumps(result,separators=(',',':'))+'\n'})
    fixtures=list({f['input']:f for f in fixtures}.values())
    assert len(fixtures)>=10,(title,len(fixtures))
    assert len({f['output'] for f in fixtures})>1,title
    bank.append(dict(id='practice-'+re.sub('[^a-z0-9]+','-',title.lower()).strip('-'),version=1,title=title,topic=topic,difficulty=difficulty,statement=description,inputFormat='One JSON value on a single line, with the fields described above. Read it using json.loads(input()).',outputFormat='One compact JSON value. Use print(json.dumps(answer, separators=(",", ":"))). Booleans must be JSON true/false. Arrays retain the stated order.',constraints=['Array and string lengths are at most 200 unless stated otherwise.','Integers have absolute value at most 10,000 unless stated otherwise.','All inputs satisfy the stated preconditions.'],examples=fixtures[:2],tests=fixtures[2:],starterCode='import json\n\ndef solve(data):\n    # Return the answer for the JSON input described in the problem.\n    pass\n\ndata = json.loads(input())\nprint(json.dumps(solve(data), separators=(",", ":")))\n',referenceSolution=preamble+'def solve(data):\n'+''.join('    '+line+'\n' for line in body.splitlines())+'data=json.loads(sys.stdin.readline())\nprint(json.dumps(solve(data),separators=(",",":")))\n',editorial={'explanation':description+' The reference implementation maintains the intermediate state needed for this operation; see its stated complexity.', 'timeComplexity':time,'spaceComplexity':space},curriculum='CodeClash interview foundations',matchEligible=False))
arrays=[[1,2,1],[3,2,1],[],[0],[-3,-2,-1],[1,2,3,4],[0,0,0],[5,-1,5,-1]]+[[rng.randint(-8,8) for _ in range(rng.randrange(1,20))] for i in range(18)]
positive=[[abs(x) for x in a] for a in arrays]
nonempty=[a for a in arrays if a]
strings=['level','abc','aabb','', 'a','racecar','abca','banana','xyzxyz','mississippi','aaabbbccc','abcdefghi']+[''.join(rng.choice('abcdef') for _ in range(rng.randrange(1,25))) for i in range(15)]
add('Duplicate manifest','Arrays & hashing','Input is an integer array. Return true if any value occurs twice.','return len(set(data)) != len(data)',arrays)
add('Distinct manifest','Arrays & hashing','Input is an integer array. Return distinct values sorted in ascending order.','return sorted(set(data))',arrays,time='O(n log n)')
add('Occurrence ledger','Arrays & hashing','Input is an integer array. Return [value,count] pairs ordered by value.','return sorted([x,c] for x,c in Counter(data).items())',arrays,time='O(n log n)')
add('Prefix ledger','Arrays & hashing','Input is an integer array. Return its inclusive prefix sums.','out=[];total=0\nfor x in data:\n    total+=x;out.append(total)\nreturn out',arrays)
add('Product exclusions','Arrays & hashing','Input is an integer array. Return the product of every other element for each position. Empty input returns []. Do not use division.','out=[1]*len(data);p=1\nfor i,x in enumerate(data):\n    out[i]=p;p*=x\np=1\nfor i in range(len(data)-1,-1,-1):\n    out[i]*=p;p*=data[i]\nreturn out',arrays,'Medium',space='O(n) output; O(1) auxiliary')
add('Longest consecutive IDs','Arrays & hashing','Input is an integer array. Return the length of its longest consecutive-value sequence, ignoring duplicates.','s=set(data);best=0\nfor x in s:\n    if x-1 not in s:\n        end=x\n        while end in s:end+=1\n        best=max(best,end-x)\nreturn best',arrays,'Medium')
add('Majority candidate','Arrays & hashing','Input is an integer array. Return the value occurring more than half the time, or null if none exists.','candidate=None;count=0\nfor x in data:\n    if count==0:candidate=x\n    count+=1 if x==candidate else -1\nreturn candidate if data and data.count(candidate)>len(data)//2 else None',arrays,space='O(1)')
add('Zero relocation','Two pointers','Input is an integer array. Return nonzero values in original order followed by all zeros.','return [x for x in data if x!=0]+[0]*data.count(0)',arrays)
add('Sorted compression','Two pointers','Input is an integer array. Sort it and return each value once.','return sorted(set(data))',arrays,time='O(n log n)')
add('Best trade','Greedy','Input is an array of nonnegative prices. Return the maximum profit from buying once and selling later, or 0.','low=math.inf;best=0\nfor price in data:\n    best=max(best,price-low);low=min(low,price)\nreturn best',positive,space='O(1)')
add('Repeated trades','Greedy','Input is an array of nonnegative prices. Return maximum profit from any number of nonoverlapping buy/sell trades.','return sum(max(0,b-a) for a,b in zip(data,data[1:]))',positive,space='O(1)')
add('Alternating parity run','Arrays & hashing','Input is an integer array. Return longest contiguous run whose adjacent values have different parity.','best=run=0;previous=None\nfor x in data:\n    run=run+1 if previous is not None and x%2!=previous%2 else 1\n    previous=x;best=max(best,run)\nreturn best',arrays,space='O(1)')
add('Increasing streak','Arrays & hashing','Input is an integer array. Return longest strictly increasing contiguous run length.','best=run=0;prev=None\nfor x in data:\n    run=run+1 if prev is not None and x>prev else 1\n    best=max(best,run);prev=x\nreturn best',arrays,space='O(1)')
add('Pivot balance','Arrays & hashing','Input is an integer array. Return the first index whose left and right sums are equal, or -1.','total=sum(data);left=0\nfor i,x in enumerate(data):\n    if left==total-left-x:return i\n    left+=x\nreturn -1',arrays,space='O(1)')
add('Square order','Two pointers','Input is a sorted integer array. Return its squares in sorted order.','out=[0]*len(data);l=0;r=len(data)-1\nfor i in range(len(data)-1,-1,-1):\n    if abs(data[l])>abs(data[r]):out[i]=data[l]**2;l+=1\n    else:out[i]=data[r]**2;r-=1\nreturn out',[sorted(a) for a in arrays])
add('Adjacent differences','Arrays & hashing','Input is an integer array. Return differences data[i+1]-data[i] in original order.','return [b-a for a,b in zip(data,data[1:])]',arrays)
add('Next warmer reading','Stack','Input is an integer array of readings. For each position return distance to next strictly greater value, or 0.','out=[0]*len(data);stack=[]\nfor i,x in enumerate(data):\n    while stack and data[stack[-1]]<x:\n        j=stack.pop();out[j]=i-j\n    stack.append(i)\nreturn out',arrays,'Medium')
add('Previous smaller reading','Stack','Input is an integer array. For each position return the index of the nearest strictly smaller value to its left, or -1.','out=[];stack=[]\nfor i,x in enumerate(data):\n    while stack and data[stack[-1]]>=x:stack.pop()\n    out.append(stack[-1] if stack else -1);stack.append(i)\nreturn out',arrays,'Medium')
add('Largest histogram block','Stack','Input is nonnegative histogram heights of unit width. Return largest rectangular area.','stack=[];best=0\nfor i,h in enumerate(data+[0]):\n    start=i\n    while stack and stack[-1][1]>h:\n        start,old=stack.pop();best=max(best,old*(i-start))\n    stack.append((start,h))\nreturn best',positive,'Hard')
add('Retained rain','Two pointers','Input is nonnegative heights. Return total rainwater retained between bars of unit width.','l=0;r=len(data)-1;lm=rm=total=0\nwhile l<=r:\n    if lm<=rm:\n        lm=max(lm,data[l]);total+=lm-data[l];l+=1\n    else:\n        rm=max(rm,data[r]);total+=rm-data[r];r-=1\nreturn total',positive,'Hard',space='O(1)')
add('Container reach','Two pointers','Input is nonnegative heights. Choose two bars and return maximum min(height[i],height[j])*(j-i), or 0.','l=0;r=len(data)-1;best=0\nwhile l<r:\n    best=max(best,min(data[l],data[r])*(r-l))\n    if data[l]<data[r]:l+=1\n    else:r-=1\nreturn best',positive,'Medium',space='O(1)')
add('Nonadjacent rewards','1-D dynamic programming','Input is nonnegative rewards. Return maximum sum from positions with no two adjacent.','a=b=0\nfor x in data:a,b=b,max(b,a+x)\nreturn b',positive,'Medium',space='O(1)')
add('Increasing subsequence length','1-D dynamic programming','Input is an integer array. Return longest strictly increasing subsequence length.','tails=[]\nfor x in data:\n    i=bisect.bisect_left(tails,x)\n    if i==len(tails):tails.append(x)\n    else:tails[i]=x\nreturn len(tails)',arrays,'Medium',time='O(n log n)')
add('Degree span','Arrays & hashing','Input is an integer array. Return length of shortest contiguous interval containing all occurrences of a most-frequent value; empty returns 0.','first={};last={};count=Counter(data)\nfor i,x in enumerate(data):first.setdefault(x,i);last[x]=i\nif not data:return 0\ndegree=max(count.values())\nreturn min(last[x]-first[x]+1 for x in count if count[x]==degree)',arrays)
add('Minimum increment cost','Greedy','Input is an integer array. Increase values until they are all distinct; return smallest total increase.','last=-math.inf;cost=0\nfor x in sorted(data):\n    y=max(x,last+1);cost+=y-x;last=y\nreturn cost',arrays,'Medium',time='O(n log n)')
add('Weighted position sum','Arrays & hashing','Input is an integer array. Return sum((i+1)*data[i]).','return sum((i+1)*x for i,x in enumerate(data))',arrays,space='O(1)')
add('Reverse message','Strings','Input is a string. Return its characters reversed.','return data[::-1]',strings)
add('Palindrome message','Two pointers','Input is a string. Return whether it reads identically forward and backward.','l=0;r=len(data)-1\nwhile l<r:\n    if data[l]!=data[r]:return False\n    l+=1;r-=1\nreturn True',strings,space='O(1)')
add('Distinct characters','Arrays & hashing','Input is a lowercase string. Return number of distinct characters.','return len(set(data))',strings,space='O(1) for fixed alphabet')
add('Run compression','Strings','Input is a string. Return [character,length] pairs for consecutive runs.','return [[k,len(list(g))] for k,g in itertools.groupby(data)]',strings)
add('Unique substring span','Sliding window','Input is a string. Return longest substring length with no repeated character.','seen={};left=best=0\nfor i,ch in enumerate(data):\n    left=max(left,seen.get(ch,-1)+1);seen[ch]=i;best=max(best,i-left+1)\nreturn best',strings,'Medium')
add('Partition message','Greedy','Input is a string. Split into as many contiguous segments as possible so no character appears in more than one segment. Return segment lengths.','last={c:i for i,c in enumerate(data)};out=[];end=start=0\nfor i,c in enumerate(data):\n    end=max(end,last[c])\n    if i==end:out.append(i-start+1);start=i+1\nreturn out',strings,'Medium')
add('Palindrome expansion','Two pointers','Input is a string. Return length of longest palindromic substring.','best=0\nfor i in range(len(data)):\n    for l,r in [(i,i),(i,i+1)]:\n        while l>=0 and r<len(data) and data[l]==data[r]:\n            best=max(best,r-l+1);l-=1;r+=1\nreturn best',strings,'Medium',time='O(n²)',space='O(1)')
add('Palindrome inventory','Two pointers','Input is a string. Return number of nonempty palindromic substrings, counting positions separately.','total=0\nfor i in range(len(data)):\n    for l,r in [(i,i),(i,i+1)]:\n        while l>=0 and r<len(data) and data[l]==data[r]:total+=1;l-=1;r+=1\nreturn total',strings,'Medium',time='O(n²)',space='O(1)')
add('Palindrome assembly','Arrays & hashing','Input is a string. Return longest palindrome length obtainable by rearranging some characters.','counts=Counter(data);even=sum(c//2*2 for c in counts.values())\nreturn even+int(any(c%2 for c in counts.values()))',strings)
add('Adjacent cancellation','Stack','Input is a string. Repeatedly remove pairs of equal adjacent characters until stable; return remaining string.','stack=[]\nfor c in data:\n    if stack and stack[-1]==c:stack.pop()\n    else:stack.append(c)\nreturn "".join(stack)',strings)
add('Lexical suffix','Strings','Input is a string. Return its lexicographically smallest suffix, including empty suffix only for empty input.','return min((data[i:] for i in range(len(data))),default="")',strings,'Medium',time='O(n²)',space='O(n)')
add('Rotation period','Strings','Input is a string. Return shortest positive period length such that repetition reconstructs the string; empty returns 0.','n=len(data);pi=[0]*n\nfor i in range(1,n):\n    j=pi[i-1]\n    while j and data[i]!=data[j]:j=pi[j-1]\n    if data[i]==data[j]:j+=1\n    pi[i]=j\nif not n:return 0\np=n-pi[-1]\nreturn p if n%p==0 else n',strings,'Medium')
add('Vowel count','Strings','Input is a lowercase string. Return count of characters in aeiou.','return sum(c in "aeiou" for c in data)',strings,space='O(1)')
add('Alphabet shift','Strings','Input is a lowercase string. Replace each letter by the next alphabet letter, wrapping z to a.','return "".join(chr((ord(c)-97+1)%26+97) for c in data)',strings)
add('Minimal palindrome deletions','2-D dynamic programming','Input is a string. Return minimum deletions needed to obtain a palindrome.','n=len(data);dp=[[0]*n for _ in range(n)]\nfor length in range(2,n+1):\n    for l in range(n-length+1):\n        r=l+length-1;dp[l][r]=dp[l+1][r-1] if data[l]==data[r] else 1+min(dp[l+1][r],dp[l][r-1])\nreturn dp[0][-1] if n else 0',strings,'Medium',time='O(n²)',space='O(n²)')
add('Palindromic subsequence','2-D dynamic programming','Input is a string. Return longest palindromic subsequence length.','n=len(data);dp=[[0]*n for _ in range(n)]\nfor i in range(n-1,-1,-1):\n    dp[i][i]=1\n    for j in range(i+1,n):dp[i][j]=2+(dp[i+1][j-1] if j>i+1 else 0) if data[i]==data[j] else max(dp[i+1][j],dp[i][j-1])\nreturn dp[0][-1] if n else 0',strings,'Medium',time='O(n²)',space='O(n²)')
add('Distinct subsequence inventory','1-D dynamic programming','Input is a string. Return number of distinct subsequences including the empty one, modulo 1000000007.','total=1;last={};mod=1000000007\nfor c in data:\n    new=(2*total-last.get(c,0))%mod;last[c]=total;total=new\nreturn total',strings,'Hard')
add('Subsequence ordering','Arrays & hashing','Input is a string. Return characters ordered by descending frequency, then alphabetically for ties, repeating each by its count.','c=Counter(data)\nreturn "".join(k*c[k] for k in sorted(c,key=lambda k:(-c[k],k)))',strings,time='O(n + a log a), a distinct characters')
add('First repeated character','Arrays & hashing','Input is a string. Return first character encountered for a second time, or null.','seen=set()\nfor c in data:\n    if c in seen:return c\n    seen.add(c)\nreturn None',strings)
add('Character ledger','Arrays & hashing','Input is a string. Return [character,count] pairs sorted by character.','return sorted([c,n] for c,n in Counter(data).items())',strings,time='O(n + a log a), a distinct characters')
add('Anagram comparison','Arrays & hashing','Input is [a,b], two lowercase strings. Return whether a and b have identical character counts.','return Counter(data[0])==Counter(data[1])',[[s,s[::-1] if i%2 else s+'z'] for i,s in enumerate(strings)])
add('Subsequence check','Two pointers','Input is [a,b], strings. Return whether a is a subsequence of b.','a,b=data;i=0\nfor c in b:\n    if i<len(a) and a[i]==c:i+=1\nreturn i==len(a)',[[s[::2] if i%2 else 'zz',s] for i,s in enumerate(strings)])
add('Common prefix','Strings','Input is a list of strings. Return longest common prefix. Empty list returns empty string.','if not data:return ""\na=min(data);b=max(data);i=0\nwhile i<min(len(a),len(b)) and a[i]==b[i]:i+=1\nreturn a[:i]',[[s,s[:len(s)//2]] for s in strings],time='O(total characters)')
add('Edit distance','2-D dynamic programming','Input is [a,b], strings. Return minimum insertions, deletions or substitutions to transform a into b.','a,b=data;prev=list(range(len(b)+1))\nfor i,x in enumerate(a,1):\n    curr=[i]\n    for j,y in enumerate(b,1):curr.append(min(curr[-1]+1,prev[j]+1,prev[j-1]+(x!=y)))\n    prev=curr\nreturn prev[-1]',[[s,s[::-1] if i%2 else s[::2]] for i,s in enumerate(strings)],'Medium',time='O(nm)',space='O(m)')
add('Common subsequence','2-D dynamic programming','Input is [a,b], strings. Return longest common subsequence length.','a,b=data;prev=[0]*(len(b)+1)\nfor x in a:\n    curr=[0]\n    for j,y in enumerate(b,1):curr.append(prev[j-1]+1 if x==y else max(prev[j],curr[-1]))\n    prev=curr\nreturn prev[-1]',[[s,s[::-1]] for s in strings],'Medium',time='O(nm)',space='O(m)')
param=[{'values':a,'k':rng.randrange(1,8)} for a in arrays]
add('Cyclic shift','Arrays & hashing','Input has values (integer array) and k (nonnegative integer). Rotate values right by k positions.','a=data["values"];n=len(a)\nif not n:return []\nk=data["k"]%n\nreturn a[-k:]+a[:-k] if k else a',param)
add('Top frequency values','Heap / priority queue','Input has values and k. Return up to k distinct values by descending frequency and ascending value for ties.','c=Counter(data["values"])\nreturn heapq.nsmallest(data["k"],c,key=lambda x:(-c[x],x))',param,'Medium',time='O(n + d log k), d distinct values')
add('Smallest selection','Heap / priority queue','Input has values and k. Return up to k smallest values sorted, retaining duplicates.','return heapq.nsmallest(data["k"],data["values"])',param,time='O(n log k)')
add('Threshold count','Binary search','Input has values and k. Return number of values strictly less than k.','return sum(x<data["k"] for x in data["values"])',param,space='O(1)')
add('Target subarray inventory','Arrays & hashing','Input has values and k. Return count of nonempty contiguous subarrays summing to k.','counts=Counter({0:1});total=answer=0\nfor x in data["values"]:\n    total+=x;answer+=counts[total-data["k"]];counts[total]+=1\nreturn answer',param,'Medium')
add('Divisible subarray inventory','Arrays & hashing','Input has values and positive k. Return count of nonempty subarrays with sum divisible by k.','counts=Counter({0:1});total=answer=0\nfor x in data["values"]:\n    total=(total+x)%data["k"];answer+=counts[total];counts[total]+=1\nreturn answer',param,'Medium')
add('Window maximums','Sliding window','Input has values and positive k. Return maximum in every full k-element window, or [] if k exceeds length.','a=data["values"];k=data["k"];q=deque();out=[]\nfor i,x in enumerate(a):\n    while q and q[0]<=i-k:q.popleft()\n    while q and a[q[-1]]<=x:q.pop()\n    q.append(i)\n    if i>=k-1:out.append(a[q[0]])\nreturn out',param,'Hard')
add('Window minimums','Sliding window','Input has values and positive k. Return minimum in every full k-element window, or [] if k exceeds length.','a=data["values"];k=data["k"];q=deque();out=[]\nfor i,x in enumerate(a):\n    while q and q[0]<=i-k:q.popleft()\n    while q and a[q[-1]]>=x:q.pop()\n    q.append(i)\n    if i>=k-1:out.append(a[q[0]])\nreturn out',param,'Medium')
add('Window medians','Heap / priority queue','Input has values and positive k. Return lower median of every full k-element window. For even k choose smaller middle value.','a=data["values"];k=data["k"];window=[];out=[]\nfor i,x in enumerate(a):\n    bisect.insort(window,x)\n    if i>=k:window.pop(bisect.bisect_left(window,a[i-k]))\n    if i>=k-1:out.append(window[(k-1)//2])\nreturn out',param,'Hard',time='O(nk)',space='O(k) plus output')
add('Pair difference inventory','Arrays & hashing','Input has values and positive k. Return count of index pairs i<j whose absolute difference is k.','seen=Counter();answer=0;k=data["k"]\nfor x in data["values"]:\n    answer+=seen[x-k]+seen[x+k];seen[x]+=1\nreturn answer',param,'Medium')
add('Closest target value','Arrays & hashing','Input has values and k. Return value closest to k, choosing smaller value on ties; empty returns null.','return min(data["values"],key=lambda x:(abs(x-data["k"]),x),default=None)',param,space='O(1)')
add('Longest bounded distinct window','Sliding window','Input has values and positive k. Return longest contiguous subarray with at most k distinct values.','a=data["values"];k=data["k"];counts=Counter();left=best=0\nfor right,x in enumerate(a):\n    counts[x]+=1\n    while len(counts)>k:\n        y=a[left];counts[y]-=1;left+=1\n        if not counts[y]:del counts[y]\n    best=max(best,right-left+1)\nreturn best',param,'Medium')
add('Exact distinct window inventory','Sliding window','Input has values and positive k. Return count of nonempty subarrays containing exactly k distinct values.','a=data["values"]\ndef atmost(k):\n    c=Counter();left=total=0\n    for r,x in enumerate(a):\n        c[x]+=1\n        while len(c)>k:\n            y=a[left];c[y]-=1;left+=1\n            if not c[y]:del c[y]\n        total+=r-left+1\n    return total\nreturn atmost(data["k"])-atmost(data["k"]-1)',param,'Hard')
add('Remove target values','Two pointers','Input has values and k. Return values unequal to k in original order.','return [x for x in data["values"] if x!=data["k"]]',param)
add('Count target triples','Two pointers','Input has values and k. Return number of index triples i<j<l whose sum equals k, retaining duplicate positions.','a=sorted(data["values"]);total=0\nfor i in range(len(a)-2):\n    l=i+1;r=len(a)-1\n    while l<r:\n        s=a[i]+a[l]+a[r]\n        if s<data["k"]:l+=1\n        elif s>data["k"]:r-=1\n        elif a[l]==a[r]:total+=(r-l+1)*(r-l)//2;break\n        else:\n            x=a[l];y=a[r];lc=rc=0\n            while l<=r and a[l]==x:lc+=1;l+=1\n            while r>=l and a[r]==y:rc+=1;r-=1\n            total+=lc*rc\nreturn total',param,'Medium',time='O(n²)')
add('Longest target-sum span','Arrays & hashing','Input has values and k. Return longest nonempty contiguous subarray length summing to k, or 0.','first={0:-1};total=best=0\nfor i,x in enumerate(data["values"]):\n    total+=x\n    if total-data["k"] in first:best=max(best,i-first[total-data["k"]])\n    first.setdefault(total,i)\nreturn best',param,'Medium')
add('Minimum target-sum span','Arrays & hashing','Input has values and k. Return shortest nonempty contiguous subarray length summing exactly to k, or 0.','latest={0:-1};total=0;best=math.inf\nfor i,x in enumerate(data["values"]):\n    total+=x\n    if total-data["k"] in latest:best=min(best,i-latest[total-data["k"]])\n    latest[total]=i\nreturn best if best<math.inf else 0',param,'Medium')
add('Integer pair reach','Two pointers','Input has values and k. Return whether two distinct positions sum to k.','seen=set()\nfor x in data["values"]:\n    if data["k"]-x in seen:return True\n    seen.add(x)\nreturn False',param)
add('Maximum target xor','Bit manipulation','Input has values (nonnegative integers) and k (nonnegative). Return maximum x XOR k among values, or 0 for empty.','return max((x^data["k"] for x in data["values"]),default=0)',[{'values':[abs(x) for x in d['values']],'k':d['k']} for d in param],space='O(1)')
add('Subset target count','Backtracking','Input has values and k. Values length is at most 18. Return number of subsets of positions summing to k, including empty subset.','counts=Counter({0:1})\nfor x in data["values"]:\n    new=counts.copy()\n    for s,c in counts.items():new[s+x]+=c\n    counts=new\nreturn counts[data["k"]]',[{'values':d['values'][:14],'k':d['k']} for d in param],'Medium',time='O(nS), S reachable sums',space='O(S)')
nums=list(range(0,25))
add('Bit population','Bit manipulation','Input is a nonnegative integer at most 10000. Return its number of set bits.','return data.bit_count()',nums,time='O(log n)',space='O(1)')
add('Population table','Bit manipulation','Input is a nonnegative integer at most 200. Return set-bit counts for every integer from 0 through input.','out=[0]*(data+1)\nfor i in range(1,data+1):out[i]=out[i>>1]+(i&1)\nreturn out',nums)
add('Power of two','Bit manipulation','Input is a nonnegative integer. Return whether it is a power of two.','return data>0 and data&(data-1)==0',nums,time='O(1)',space='O(1)')
add('Power of three','Math & geometry','Input is a nonnegative integer. Return whether it is a power of three.','if data<1:return False\nwhile data%3==0:data//=3\nreturn data==1',nums,time='O(log n)',space='O(1)')
add('Fibonacci marker','1-D dynamic programming','Input is n, 0<=n<=100. Return F(n), where F(0)=0 and F(1)=1.','a,b=0,1\nfor _ in range(data):a,b=b,a+b\nreturn a',nums,space='O(1) integers')
add('Staircase routes','1-D dynamic programming','Input is n, 0<=n<=100. Steps may have length 1 or 2. Return number of ordered ways to climb n steps. There is one empty route for n=0.','a=b=1\nfor _ in range(data):a,b=b,a+b\nreturn a',nums,space='O(1) integers')
add('Three-step staircase','1-D dynamic programming','Input is n, 0<=n<=100. Steps may have length 1,2 or 3. Return ordered route count.','dp=[0]*(data+1);dp[0]=1\nfor i in range(1,data+1):dp[i]=sum(dp[i-k] for k in (1,2,3) if i>=k)\nreturn dp[-1]',nums)
add('Catalan structures','2-D dynamic programming','Input is n, 0<=n<=20. Return number of different binary search tree shapes containing n keys.','dp=[0]*(data+1);dp[0]=1\nfor n in range(1,data+1):dp[n]=sum(dp[l]*dp[n-1-l] for l in range(n))\nreturn dp[-1]',list(range(21)),'Medium',time='O(n²)')
add('Prime inventory','Math & geometry','Input is n, 0<=n<=10000. Return count of prime numbers strictly less than n.','if data<2:return 0\nsieve=[True]*data;sieve[0]=sieve[1]=False\nfor p in range(2,math.isqrt(data-1)+1):\n    if sieve[p]:\n        for j in range(p*p,data,p):sieve[j]=False\nreturn sum(sieve)',nums,'Medium',time='O(n log log n)')
add('Factor ledger','Math & geometry','Input is a positive integer at most 10000. Return its positive divisors sorted.','small=[];large=[]\nfor i in range(1,math.isqrt(data)+1):\n    if data%i==0:\n        small.append(i)\n        if i*i!=data:large.append(data//i)\nreturn small+large[::-1]',list(range(1,26)),time='O(sqrt(n))',space='O(number of divisors)')
add('Trailing factorial zeros','Math & geometry','Input is a nonnegative integer. Return trailing decimal zeros in its factorial.','total=0\nwhile data:\n    data//=5;total+=data\nreturn total',nums,time='O(log n)',space='O(1)')
add('Digital root','Math & geometry','Input is a nonnegative integer. Repeatedly sum decimal digits until one remains; return that digit.','return 0 if data==0 else 1+(data-1)%9',nums,time='O(1)',space='O(1)')
add('Decimal reversal','Math & geometry','Input is a nonnegative integer. Return integer obtained by reversing decimal digits, dropping leading zeros.','return int(str(data)[::-1])',nums,time='O(log n)',space='O(log n)')
add('Digit ledger','Math & geometry','Input is a nonnegative integer. Return ten counts for decimal digits 0 through 9. Zero has one zero digit.','c=Counter(str(data));return [c[str(i)] for i in range(10)]',nums,time='O(log n)',space='O(1)')
add('Happy marker','Math & geometry','Input is a positive integer. Repeatedly replace by sum of squares of digits. Return whether 1 is eventually reached.','seen=set()\nwhile data!=1 and data not in seen:\n    seen.add(data);data=sum(int(c)**2 for c in str(data))\nreturn data==1',list(range(1,26)),time='O(log n) initial digits plus bounded cycle',space='O(log n) digit storage plus bounded states')
add('Square feasibility','Math & geometry','Input is a nonnegative integer. Return whether it is a perfect square.','return math.isqrt(data)**2==data',nums,time='O(log n)',space='O(1)')
add('Triangular feasibility','Binary search','Input is a nonnegative integer. Return largest k such that k*(k+1)/2 <= input.','return (math.isqrt(8*data+1)-1)//2',nums,time='O(log n)',space='O(1)')
add('Integer square root','Binary search','Input is a nonnegative integer. Return floor of its square root without floating point.','l=0;r=data\nwhile l<=r:\n    m=(l+r)//2\n    if m*m<=data:l=m+1\n    else:r=m-1\nreturn r',nums,time='O(log n)',space='O(1)')
add('Balanced parenthesis count','Backtracking','Input is n, 0<=n<=8. Return number of balanced parenthesis strings with n pairs.','def walk(opened,closed):\n    if closed==data:return 1\n    return (walk(opened+1,closed) if opened<data else 0)+(walk(opened,closed+1) if closed<opened else 0)\nreturn walk(0,0)',list(range(9))+list(range(9,12)),'Medium',time='O(C_n * n), C_n Catalan count',space='O(n)')
add('Gray traversal','Bit manipulation','Input is n, 0<=n<=10. Return binary-reflected Gray-code sequence of integers.','return [i^(i>>1) for i in range(1<<data)]',list(range(11)),'Medium',time='O(2^n)',space='O(2^n)')
add('Binary reversal byte','Bit manipulation','Input is an integer from 0 to 255. Return value of reversing its eight binary bits.','out=0\nfor _ in range(8):out=(out<<1)|(data&1);data>>=1\nreturn out',nums,time='O(1)',space='O(1)')
add('Range bitwise conjunction','Bit manipulation','Input is [left,right] with 0<=left<=right. Return bitwise AND of all integers in this inclusive range.','l,r=data;shift=0\nwhile l<r:l>>=1;r>>=1;shift+=1\nreturn l<<shift',[[i,i+(i%5)] for i in nums],'Medium',time='O(log right)',space='O(1)')
add('Euclidean divisor','Math & geometry','Input is [a,b], nonnegative integers not both zero. Return greatest common divisor.','a,b=data\nwhile b:a,b=b,a%b\nreturn a',[[i+1,(i+1)*(i%4+1)] for i in nums],time='O(log min(a,b))',space='O(1)')
add('Least common period','Math & geometry','Input is [a,b], positive integers. Return least common multiple.','a,b=data;return a//math.gcd(a,b)*b',[[i+1,i%7+1] for i in nums],time='O(log min(a,b))',space='O(1)')
add('Pascal row','1-D dynamic programming','Input is n, 0<=n<=100. Return zero-indexed row n of Pascal triangle.','row=[1]\nfor i in range(1,data+1):row.append(row[-1]*(data-i+1)//i)\nreturn row',nums)
add('Binary adjacency avoidance','1-D dynamic programming','Input is n, 0<=n<=100. Return number of binary strings of length n with no adjacent ones.','zero,one=1,0\nfor _ in range(data):zero,one=zero+one,zero\nreturn zero+one',nums,space='O(1) integers')
add('Domino strip routes','1-D dynamic programming','Input is n, 0<=n<=100. Return ways to tile a 2-by-n strip using 2-by-1 dominoes.','a=b=1\nfor _ in range(data):a,b=b,a+b\nreturn a',nums,space='O(1) integers')
add('Integer partitions','2-D dynamic programming','Input is n, 0<=n<=100. Return ways to write n as a nondecreasing sequence of positive integers; empty partition counts once.','dp=[0]*(data+1);dp[0]=1\nfor part in range(1,data+1):\n    for s in range(part,data+1):dp[s]+=dp[s-part]\nreturn dp[-1]',nums,'Medium',time='O(n²)')
graphs=[]
for n in range(1,18):
    edges=[[u,v] for u in range(n) for v in range(u+1,n) if rng.random()<.2]
    graphs.append({'n':n,'edges':edges})
add('Connected districts','Graphs','Input has n vertices labeled 0..n-1 and edges, an undirected simple graph. Return number of connected components.','n=data["n"];adj=[[] for _ in range(n)]\nfor u,v in data["edges"]:adj[u].append(v);adj[v].append(u)\nseen=set();count=0\nfor root in range(n):\n    if root in seen:continue\n    count+=1;stack=[root];seen.add(root)\n    while stack:\n        for v in adj[stack.pop()]:\n            if v not in seen:seen.add(v);stack.append(v)\nreturn count',graphs,'Medium',time='O(V+E)',space='O(V+E)')
add('District reach','Graphs','Input has n and undirected edges. Return sorted labels reachable from vertex 0.','adj=[[] for _ in range(data["n"])]\nfor u,v in data["edges"]:adj[u].append(v);adj[v].append(u)\nseen={0};stack=[0]\nwhile stack:\n    for v in adj[stack.pop()]:\n        if v not in seen:seen.add(v);stack.append(v)\nreturn sorted(seen)',graphs,'Easy',time='O(V+E+V log V)',space='O(V+E)')
add('Route hop count','Graphs','Input has n and undirected edges. Return shortest number of edges from vertex 0 to n-1, or -1 if unreachable.','adj=[[] for _ in range(data["n"])]\nfor u,v in data["edges"]:adj[u].append(v);adj[v].append(u)\nq=deque([(0,0)]);seen={0}\nwhile q:\n    u,d=q.popleft()\n    if u==data["n"]-1:return d\n    for v in adj[u]:\n        if v not in seen:seen.add(v);q.append((v,d+1))\nreturn -1',graphs,'Medium',time='O(V+E)',space='O(V+E)')
add('Bipartite districts','Graphs','Input has n and undirected edges. Return whether vertices can be colored with two colors so edge endpoints differ.','adj=[[] for _ in range(data["n"])]\nfor u,v in data["edges"]:adj[u].append(v);adj[v].append(u)\ncolors={}\nfor root in range(data["n"]):\n    if root in colors:continue\n    colors[root]=0;q=deque([root])\n    while q:\n        u=q.popleft()\n        for v in adj[u]:\n            if v in colors:\n                if colors[v]==colors[u]:return False\n            else:colors[v]=1-colors[u];q.append(v)\nreturn True',graphs,'Medium',time='O(V+E)',space='O(V+E)')
add('Cycle detection','Graphs','Input has n and undirected simple edges. Return whether a cycle exists.','parent=list(range(data["n"]))\ndef find(x):\n    while parent[x]!=x:parent[x]=parent[parent[x]];x=parent[x]\n    return x\nfor u,v in data["edges"]:\n    a,b=find(u),find(v)\n    if a==b:return True\n    parent[a]=b\nreturn False',graphs,'Medium',time='O(E log V) amortized with path compression',space='O(V)')
add('Degree ledger','Graphs','Input has n and undirected edges. Return degree of each vertex in label order.','out=[0]*data["n"]\nfor u,v in data["edges"]:out[u]+=1;out[v]+=1\nreturn out',graphs,time='O(V+E)',space='O(V)')
add('Dependency order','Graphs','Input has n and directed edges [u,v] meaning u must precede v. Return lexicographically smallest topological ordering, or [] for a cycle.','n=data["n"];adj=[[] for _ in range(n)];deg=[0]*n\nfor u,v in data["edges"]:adj[u].append(v);deg[v]+=1\nq=[u for u in range(n) if deg[u]==0];heapq.heapify(q);out=[]\nwhile q:\n    u=heapq.heappop(q);out.append(u)\n    for v in adj[u]:\n        deg[v]-=1\n        if deg[v]==0:heapq.heappush(q,v)\nreturn out if len(out)==n else []',graphs+[{'n':n,'edges':[[i,(i+1)%n] for i in range(n)]} for n in range(2,8)],'Medium',time='O(E+V log V)',space='O(V+E)')
add('Dependency depth','Graphs','Input has n and acyclic directed edges. Return maximum number of vertices along a directed path.','n=data["n"];adj=[[] for _ in range(n)];deg=[0]*n;depth=[1]*n\nfor u,v in data["edges"]:adj[u].append(v);deg[v]+=1\nq=deque(i for i in range(n) if deg[i]==0)\nwhile q:\n    u=q.popleft()\n    for v in adj[u]:\n        depth[v]=max(depth[v],depth[u]+1);deg[v]-=1\n        if deg[v]==0:q.append(v)\nreturn max(depth,default=0)',graphs,'Medium',time='O(V+E)',space='O(V+E)')
weighted=[{'n':g['n'],'edges':[[u,v,rng.randint(1,9)] for u,v in g['edges']]} for g in graphs]
add('Cheapest route','Advanced graphs','Input has n and weighted undirected edges [u,v,w], w>0. Return shortest cost from 0 to n-1, or -1.','n=data["n"];adj=[[] for _ in range(n)]\nfor u,v,w in data["edges"]:adj[u].append((v,w));adj[v].append((u,w))\ndist=[math.inf]*n;dist[0]=0;q=[(0,0)]\nwhile q:\n    cost,u=heapq.heappop(q)\n    if cost!=dist[u]:continue\n    for v,w in adj[u]:\n        if cost+w<dist[v]:dist[v]=cost+w;heapq.heappush(q,(cost+w,v))\nreturn dist[-1] if dist[-1]<math.inf else -1',weighted,'Medium',time='O((V+E) log V)',space='O(V+E)')
add('Spanning connection cost','Advanced graphs','Input has n and weighted undirected edges [u,v,w]. Return minimum spanning tree cost, or -1 if disconnected.','n=data["n"];parent=list(range(n));size=[1]*n\ndef find(x):\n    while x!=parent[x]:parent[x]=parent[parent[x]];x=parent[x]\n    return x\ncount=cost=0\nfor u,v,w in sorted(data["edges"],key=lambda e:e[2]):\n    a,b=find(u),find(v)\n    if a!=b:\n        if size[a]<size[b]:a,b=b,a\n        parent[b]=a;size[a]+=size[b];cost+=w;count+=1\nreturn cost if count==n-1 else -1',weighted,'Hard',time='O(E log E)',space='O(V)')
matrices=[[[rng.randrange(2) for _ in range(rng.randrange(1,7))] for r in range(1)] for _ in range(12)]
matrices += [[[rng.randrange(2) for _ in range(n)] for _ in range(n)] for n in range(2,8)]
add('Island count','Graphs','Input is a nonempty rectangular matrix of 0 and 1. Count four-directionally connected groups of ones.','rows=len(data);cols=len(data[0]);seen=set();count=0\nfor r in range(rows):\n    for c in range(cols):\n        if not data[r][c] or (r,c) in seen:continue\n        count+=1;seen.add((r,c));stack=[(r,c)]\n        while stack:\n            x,y=stack.pop()\n            for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):\n                if 0<=a<rows and 0<=b<cols and data[a][b] and (a,b) not in seen:seen.add((a,b));stack.append((a,b))\nreturn count',matrices,'Medium',time='O(RC)',space='O(RC)')
add('Largest island','Graphs','Input is a nonempty rectangular binary matrix. Return largest four-connected group of ones area, or 0.','rows=len(data);cols=len(data[0]);seen=set();best=0\nfor r in range(rows):\n    for c in range(cols):\n        if not data[r][c] or (r,c) in seen:continue\n        seen.add((r,c));stack=[(r,c)];area=0\n        while stack:\n            x,y=stack.pop();area+=1\n            for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):\n                if 0<=a<rows and 0<=b<cols and data[a][b] and (a,b) not in seen:seen.add((a,b));stack.append((a,b))\n        best=max(best,area)\nreturn best',matrices,'Medium',time='O(RC)',space='O(RC)')
add('Island perimeter','Math & geometry','Input is a nonempty rectangular binary matrix. Return total exposed sides of all one-valued cells.','rows=len(data);cols=len(data[0]);total=0\nfor r in range(rows):\n    for c in range(cols):\n        if data[r][c]:\n            total+=4\n            if r and data[r-1][c]:total-=2\n            if c and data[r][c-1]:total-=2\nreturn total',matrices,time='O(RC)',space='O(1)')
add('Obstacle grid routes','2-D dynamic programming','Input is a nonempty rectangular matrix; 1 blocks a cell, 0 is open. Return paths top-left to bottom-right moving only down/right.','cols=len(data[0]);dp=[0]*cols;dp[0]=1\nfor row in data:\n    for c,x in enumerate(row):\n        if x:dp[c]=0\n        elif c:dp[c]+=dp[c-1]\nreturn dp[-1]',matrices,'Medium',time='O(RC)',space='O(C)')
add('Largest square patch','2-D dynamic programming','Input is a nonempty rectangular binary matrix. Return area of largest square containing only ones.','cols=len(data[0]);prev=[0]*(cols+1);best=0\nfor row in data:\n    curr=[0]*(cols+1)\n    for c,x in enumerate(row,1):\n        if x:curr[c]=1+min(prev[c],prev[c-1],curr[c-1]);best=max(best,curr[c])\n    prev=curr\nreturn best*best',matrices,'Medium',time='O(RC)',space='O(C)')
add('Spiral scan','Math & geometry','Input is a nonempty rectangular integer matrix. Return elements in clockwise spiral order from top-left.','top=left=0;bottom=len(data)-1;right=len(data[0])-1;out=[]\nwhile top<=bottom and left<=right:\n    out.extend(data[top][left:right+1]);top+=1\n    for r in range(top,bottom+1):out.append(data[r][right])\n    right-=1\n    if top<=bottom:out.extend(data[bottom][left:right+1][::-1]);bottom-=1\n    if left<=right:\n        for r in range(bottom,top-1,-1):out.append(data[r][left])\n        left+=1\nreturn out',matrices,'Medium',time='O(RC)',space='O(RC) output')
add('Matrix transpose','Math & geometry','Input is a nonempty rectangular integer matrix. Return its transpose.','return [list(column) for column in zip(*data)]',matrices,time='O(RC)',space='O(RC)')
add('Zero row propagation','Math & geometry','Input is a nonempty rectangular integer matrix. If a cell equals zero, its entire row and column become zero simultaneously. Return resulting matrix.','rows={r for r,row in enumerate(data) if 0 in row};cols={c for row in data for c,x in enumerate(row) if x==0}\nreturn [[0 if r in rows or c in cols else x for c,x in enumerate(row)] for r,row in enumerate(data)]',matrices,'Medium',time='O(RC)',space='O(R+C) auxiliary plus output')
trees=[a for a in nonempty]
add('Heap-index tree depth','Trees','Input is a nonempty integer array representing a complete binary tree: children of i are 2i+1 and 2i+2 when present. Return its depth in nodes.','return len(data).bit_length()',trees,time='O(1)',space='O(1)')
add('Heap-index inorder','Trees','Input is a nonempty integer array representing a complete binary tree with children 2i+1 and 2i+2. Return inorder values.','out=[]\ndef walk(i):\n    if i>=len(data):return\n    walk(2*i+1);out.append(data[i]);walk(2*i+2)\nwalk(0);return out',trees,time='O(n)',space='O(log n) auxiliary plus output')
add('Heap-index preorder','Trees','Input is a nonempty integer array representing a complete binary tree with children 2i+1 and 2i+2. Return preorder values.','out=[]\ndef walk(i):\n    if i>=len(data):return\n    out.append(data[i]);walk(2*i+1);walk(2*i+2)\nwalk(0);return out',trees,time='O(n)',space='O(log n) auxiliary plus output')
add('Heap-index postorder','Trees','Input is a nonempty integer array representing a complete binary tree with children 2i+1 and 2i+2. Return postorder values.','out=[]\ndef walk(i):\n    if i>=len(data):return\n    walk(2*i+1);walk(2*i+2);out.append(data[i])\nwalk(0);return out',trees,time='O(n)',space='O(log n) auxiliary plus output')
add('Complete tree right view','Trees','Input is a nonempty integer array representing a complete binary tree. Return rightmost value at every level from root downward.','out=[];start=0;width=1\nwhile start<len(data):out.append(data[min(len(data),start+width)-1]);start+=width;width*=2\nreturn out',trees,time='O(log n)',space='O(log n) output')
add('Maximum tree path','Trees','Input is a nonempty integer array representing a complete binary tree. Return largest sum on any nonempty simple path between nodes.','best=-math.inf\ndef walk(i):\n    nonlocal best\n    if i>=len(data):return 0\n    l=max(0,walk(2*i+1));r=max(0,walk(2*i+2));best=max(best,data[i]+l+r)\n    return data[i]+max(l,r)\nwalk(0);return best',trees,'Hard',time='O(n)',space='O(log n)')
intervals=[[[x,x+rng.randrange(1,8)] for x in a] for a in arrays]
add('Interval union','Intervals','Input is a list of closed intervals [start,end], start<end. Merge overlapping or touching intervals and return sorted merged intervals.','out=[]\nfor a,b in sorted(data):\n    if out and a<=out[-1][1]:out[-1][1]=max(out[-1][1],b)\n    else:out.append([a,b])\nreturn out',intervals,'Medium',time='O(n log n)')
add('Meeting capacity','Intervals','Input is a list of half-open intervals [start,end], start<end. Return minimum rooms so overlapping meetings use different rooms.','events=[]\nfor a,b in data:events.extend([(a,1),(b,-1)])\ncurrent=best=0\nfor _,delta in sorted(events):current+=delta;best=max(best,current)\nreturn best',intervals,'Medium',time='O(n log n)')
add('Nonoverlapping appointment count','Greedy','Input is a list of half-open intervals [start,end]. Return maximum number of mutually nonoverlapping appointments.','end=-math.inf;count=0\nfor a,b in sorted(data,key=lambda p:p[1]):\n    if a>=end:count+=1;end=b\nreturn count',intervals,'Medium',time='O(n log n)')
add('Minimum interval removals','Intervals','Input is a list of half-open intervals [start,end]. Return smallest number of intervals to remove so none overlap.','end=-math.inf;kept=0\nfor a,b in sorted(data,key=lambda p:p[1]):\n    if a>=end:kept+=1;end=b\nreturn len(data)-kept',intervals,'Medium',time='O(n log n)')
add('Covered duration','Intervals','Input is a list of half-open intervals [start,end]. Return total duration covered by at least one interval.','end=-math.inf;total=0\nfor a,b in sorted(data):\n    total+=max(0,b-max(a,end));end=max(end,b)\nreturn total',intervals,'Medium',time='O(n log n)')
add('Circular rewards','1-D dynamic programming','Input is a nonnegative reward array arranged in a circle. Pick nonadjacent positions for maximum sum; first and last are adjacent.','def linear(a):\n    x=y=0\n    for v in a:x,y=y,max(y,x+v)\n    return y\nif len(data)<=1:return sum(data)\nreturn max(linear(data[1:]),linear(data[:-1]))',positive,'Medium',space='O(n) slices')
add('Minimum coin count','1-D dynamic programming','Input has values (positive coin denominations) and k (target >=0). Coins are unlimited; return minimum coins for k, or -1.','target=data["k"];dp=[0]+[target+1]*target\nfor s in range(1,target+1):\n    for c in data["values"]:\n        if c<=s:dp[s]=min(dp[s],dp[s-c]+1)\nreturn dp[-1] if dp[-1]<=target else -1',[{'values':sorted(set(abs(x)+1 for x in a)),'k':i} for i,a in enumerate(arrays)],'Medium',time='O(nk)',space='O(k)')
add('Linked chain group reversal','Linked lists','Input has values, a singly linked chain listed in order, and positive k. Reverse each complete k-node group. Leave a shorter final group unchanged. Return resulting values.','a=data["values"];k=data["k"];out=[]\nfor i in range(0,len(a),k):\n    group=a[i:i+k];out.extend(group[::-1] if len(group)==k else group)\nreturn out',param,'Medium',space='O(n) output')
# The catalog contains distinct original tasks, with no copied provider statements.
bank=[p for p in bank if p['title']!='Sorted compression']
wordcases=[{'words':[s[:i] for i in range(1,min(len(s),7)+1)],'prefix':s[:2] if index%2 else 'zz'} for index,s in enumerate(strings) if s]
add('Prefix directory','Tries','Input has words (lowercase strings) and prefix. Return number of words starting with prefix, counting duplicates.','root={}\nfor word in data["words"]:\n    node=root\n    for c in word:node=node.setdefault(c,{})\n    node["#"]=node.get("#",0)+1\nnode=root\nfor c in data["prefix"]:\n    if c not in node:return 0\n    node=node[c]\ndef count(node):return node.get("#",0)+sum(count(v) for k,v in node.items() if k!="#")\nreturn count(node)',wordcases,'Medium',time='O(total word characters)',space='O(total word characters)')
add('Prefix suggestions','Tries','Input has words and prefix. Return distinct words starting with prefix, sorted alphabetically.','root={}\nfor word in data["words"]:\n    node=root\n    for c in word:node=node.setdefault(c,{})\n    node["#"]=True\nnode=root\nfor c in data["prefix"]:\n    if c not in node:return []\n    node=node[c]\nout=[]\ndef visit(node,word):\n    if "#" in node:out.append(word)\n    for c in sorted(k for k in node if k!="#"):visit(node[c],word+c)\nvisit(node,data["prefix"]);return out',wordcases,'Medium',time='O(total word characters + output characters + trie child sorting)',space='O(total word characters)')
add('Buildable word','Tries','Input is a list of lowercase words. Return longest word whose every nonempty prefix is also present; ties choose lexicographically smallest. Return empty string if none.','built={""};best=""\nfor word in sorted(data):\n    if word[:-1] in built:\n        built.add(word)\n        if len(word)>len(best):best=word\nreturn best',[d['words'] for d in wordcases],'Medium',time='O(W log W * L)',space='O(total word characters)')
editorial_notes = {'Duplicate manifest': 'Insert each value into a set. If a value is already present, there is a duplicate. The reference uses the equivalent comparison between the set size and the input length.', 'Distinct manifest': 'A set removes duplicate values. Sort the remaining values so the answer has the required ascending order.', 'Occurrence ledger': 'Count occurrences in a dictionary, then emit the value-count pairs in sorted value order. Keeping counts separate from output ordering handles negative values and duplicates.', 'Prefix ledger': 'Maintain a running sum. After reading each element, append the current sum; each prefix therefore includes the current element exactly once.', 'Product exclusions': 'Build prefix products from the left and suffix products from the right. At each position, multiply the products on either side. This avoids division and also handles zero values.', 'Longest consecutive IDs': 'Store values in a set. Start a streak only when the preceding integer is absent, then walk forward until the streak ends. Every distinct value participates in at most one forward walk.', 'Unique substring span': 'Use a sliding window and record the last position of each character. When a character repeats inside the window, move its left boundary past that earlier position.', 'Longest bounded distinct window': 'Extend a sliding window and keep counts of array values. While the number of distinct values exceeds k, shrink from the left and remove zero counts. Record the largest valid window.', 'Target subarray inventory': 'Track prefix sums and how often each has occurred. For a current sum s, every earlier prefix sum s-k identifies a subarray totaling k. Add those counts before recording s.', 'Longest target-sum span': 'Record the earliest index of each prefix sum. If current sum minus target appeared earlier, the span between those positions totals the target. Retaining the earliest occurrence maximizes length.', 'Minimum target-sum span': 'Track each prefix sum and its latest position. If the current sum minus the target appeared earlier, the intervening nonempty span totals the target. Keeping the latest occurrence minimizes its length. Check before recording the current prefix so a zero target cannot create an empty span. This works with negative values and zeros.', 'Retained rain': 'Track the tallest wall on each side. Process the side with the lower bound, where trapped water is determined by that bound minus the current height. Move inward until the pointers meet.', 'Largest histogram block': 'Maintain a stack of increasing bar heights and their starting positions. When a shorter bar arrives, pop taller bars and compute rectangles ending at the current position. A final zero-height sentinel flushes remaining bars.', 'Next warmer reading': 'Keep unresolved indices in a decreasing temperature stack. A warmer reading resolves all smaller temperatures at the top; the index differences are their waiting times.', 'Interval union': 'Sort intervals by start. Merge the next interval when it overlaps the current merged interval, extending the end as needed; otherwise start a new interval.', 'Minimum interval removals': 'Sort appointments by end time and greedily keep the next nonoverlapping interval. An earlier finishing choice leaves at least as much room for future intervals. Removed count is total minus kept count.', 'Circular rewards': 'The first and last positions cannot both be chosen. Solve the linear nonadjacent-reward problem twice, excluding the first position once and the last position once, then take the better answer.', 'Minimum coin count': 'Let dp[s] be the fewest coins needed for sum s. Initialize zero to zero and other sums as unreachable. For every usable coin c, update dp[s] from dp[s-c]+1. Return -1 if the target stays unreachable.', 'Prefix directory': 'Insert words into a trie, with a terminal count preserving duplicates. Follow the requested prefix, then sum terminal counts in that subtree. A missing prefix edge means zero matches.', 'Prefix suggestions': 'Build a trie with terminal markers, follow the prefix, then visit child characters in sorted order. Emit a word at each terminal marker; this yields unique suggestions in lexical order.', 'Buildable word': 'Visit words in lexical order and maintain the set of buildable prefixes, starting with the empty string. A word is buildable when its immediate shorter prefix is buildable. Replace the best only for a strictly longer word, preserving the lexical tie-break.'}
for entry in bank:
    if entry["title"] in editorial_notes:entry["editorial"]["explanation"]=editorial_notes[entry["title"]]
assert len(bank)==133,len(bank)
for p in bank:
    if p['title']=='Balanced parenthesis count':p['statement']=p['statement'].replace('<=8','<=11')
Path('database/practice-bank.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Authored',len(bank),'practice questions with',sum(len(p['examples'])+len(p['tests']) for p in bank),'fixtures')
